import type { Metadata } from "next";
import { SITE_NAME, SITE_URL } from "./domain";

export interface SEOOptions {
  title: string;
  description: string;
  path?: string;
  image?: string;
  keywords?: string;
  type?: "website" | "article";
  robots?: string;
}

export const DEFAULT_IMAGE = `${SITE_URL}/og-image.png`;
export const DEFAULT_ROBOTS =
  "index,follow,max-image-preview:large,max-snippet:-1,max-video-preview:-1";

/**
 * Builds a Next.js `Metadata` object (consumed by `generateMetadata` /
 * a page's `metadata` export) from the same options shape the app used to
 * pass to react-router's meta descriptors.
 */
export function createMeta({
  title,
  description,
  path = "",
  image = DEFAULT_IMAGE,
  keywords,
  type = "article",
  robots = DEFAULT_ROBOTS,
}: SEOOptions): Metadata {
  const url = `${SITE_URL}${path}`;

  return {
    title,
    description,
    keywords,
    robots,
    alternates: {
      canonical: url,
    },
    openGraph: {
      title,
      description,
      type,
      url,
      siteName: SITE_NAME,
      locale: "en_US",
      images: [
        {
          url: image,
          width: 1200,
          height: 630,
        },
      ],
    },
    twitter: {
      card: "summary_large_image",
      title,
      description,
      images: [image],
    },
  };
}
