import Link from "next/link";
import type { ReactNode } from "react";
import Footer from "~/components/Footer/Footer";
import Header from "~/components/Header/Header";
import "./ErrorLayout.css";

type Props = {
  /** Badge text, e.g. "404" or "500". Omit to hide the badge. */
  code?: string;
  title: ReactNode;
  description?: ReactNode;
  /** Emoji or node shown under the description. Omit to hide. */
  illustration?: ReactNode;
  /** Show the "Return to Home" button. */
  showHome?: boolean;
  /** Extra content rendered above the button (e.g. dev stack trace). */
  children?: ReactNode;
};

const ErrorLayout = ({
  code,
  title,
  description,
  illustration,
  showHome = false,
  children,
}: Props) => {
  return (
    <section className="app-section error-section">
      <Header />

      <div className="error-container">
        {code && <p className="error-code">{code}</p>}

        <h1 className="title">{title}</h1>

        {description && <p className="subtitle">{description}</p>}

        {illustration && <div className="error-illustration">{illustration}</div>}

        {children}

        {showHome && (
          <Link href="/" className="action">
            Return to Home
          </Link>
        )}
      </div>

      <Footer />
    </section>
  );
};

export default ErrorLayout;
